class ConfigModeloNominaCategoria extends BaseConfigModeloNominaCategoria {

    /**
     * Obtener las categorias dado un identificador de modelo de nomina.
	 *
     * @param int $idconfmod		Identificador del modelo de nomina.
	 *
     * @return array    Listado de categorias.
     */
    public static function obtenerCategoriasPorIdModelo($idconfmod) {
		
        //Devolviendo el listado de configuraci�n de las categorias.
        return Doctrine_Query::create()
                ->from('ConfigModeloNominaCategoria')
                ->where('idconfmodelonomina = ?', $idconfmod)
                ->fetchArray();
    }
	
   /**
     * Obtener un configuraci�n dado el identificador.
     * 
     * @param int $idconfig                 Identificador de la configuraci�n.
     * @return ConfigModeloNomina    		Objeto configuraci�n de modelos de n�mina (clase del dominio).
     */
    public static function obtenerObjConfigModelosNominaDadoId($idconfig) { 
        return Doctrine::getTable('ConfigModeloNomina')->find($idconfig);
    }

    /**
     * Eliminar todas las categor�as dado el identificador del modelo.
     * 
     * @param int $idconfmod        Identificador del modelo de nomina.
     */
    public static function eliminarTodasCategoriasDadoIdModelo($idconfmod) {
        return Doctrine_Query::create()
                ->delete()
                ->from('ConfigModeloNominaCategoria')
                ->where('idconfmodelonomina = ?', $idconfmod)
                ->execute();
    }
    /**
     * Obtener las categorias de persona
     *
     * @param int $idconfmod        Identificador del modelo de nomina.
     */

    public static function getNomCategoriasdadoid($idcategoria) {
        $sql = "select pc.idcategoriapersona,pc.denominacion
					from mod_personaext.nom_categoriapersona pc

					where pc.idcategoriapersona = ?;";

        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();
        return $conn->fetchAll($sql, array($idcategoria));
    }

}